(() => {
  'use strict';
  const VERSION='4.3.2', ORIGIN='https://neo.holytemples.org';
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
