  class Widget extends HTMLElement{connectedCallback(){if(this._on)return;this._on=true;this.root=this.attachShadow({mode:'open'});this.shell('<div class="k">NEO System</div><h2>Connecting…</h2><div class="muted">Opening the governed public bridge.</div>');this.load()}shell(x){this.root.innerHTML=`<style>${css}</style><section class="neo">${x}<div class="foot">NEO Temple Suite v${VERSION}</div></section>`}fail(e){this.shell(`<div class="k">NEO System</div><h2>Connection paused</h2><div class="error">${esc(e.message)}. Refresh to try again.</div>`)}}
  class NeoServiceGrid extends Widget{async load(){try{const p=await get('/api'),s=p.system?.services||[];this.shell(`<div class="k">Live service registry</div><h2>NEO System Network</h2><div class="grid">${s.map(i=>`<a class="card" href="${safe(i.url)}"><div class="name">${esc(i.name)}</div><div class="muted">${esc(i.role)}</div><div class="tag"><span class="dot"></span> Online</div></a>`).join('')}</div>`)}catch(e){this.fail(e)}}}
  class NeoNomniValue extends Widget{async load(){try{const v=await get('/api/nomni/value');this.shell(`<div class="k">Market-observed value</div><h2>NOMNI Infinity Dollar</h2><div class="value">∞1 = $${esc(v.usd||'—')}</div><div class="grid"><div class="card"><div class="muted">XCP</div><div class="name">${esc(v.xcp||'—')}</div></div><div class="card"><div class="muted">BTC</div><div class="name">${esc(v.btc||'Not observed')}</div></div></div><p class="muted">Observed market data—not a guaranteed redemption peg.</p>`)}catch(e){this.fail(e)}}}
  class NeoNoogleSearch extends Widget{async load(){this.shell('<div class="k">World knowledge gateway</div><h2>Noogle Search</h2><form class="row"><input class="input" name="q" type="search" minlength="2" placeholder="Search the World Library" aria-label="Search the World Library" required><button class="button">Search</button></form><div class="results" aria-live="polite"></div>');const f=this.root.querySelector('form');f.addEventListener('submit',async e=>{e.preventDefault();const q=new FormData(f).get('q').trim(),b=f.querySelector('button'),o=this.root.querySelector('.results');if(!q)return;b.disabled=true;o.innerHTML='<div class="muted">Searching…</div>';try{const p=await get(`/noogle/search?q=${encodeURIComponent(q)}`);o.innerHTML=p.records?.length?p.records.slice(0,12).map(i=>`<a class="result" href="${safe(i.sourceUrl||i.mediaUrl,'https://holytemples.org/world-library/')}"><div class="name">${esc(i.title)}</div><div class="muted">${esc(i.author||i.resourceType||'')}</div></a>`).join(''):'<div class="muted">No public records matched that search.</div>'}catch(x){o.innerHTML=`<div class="error">${esc(x.message)}</div>`}finally{b.disabled=false}})}}
  class NeoLaunchers extends Widget{async load(){const k=this.getAttribute('kind')||'all',a=[['NEOpass','Identity and member access','https://neopass.holytemples.org'],['NEOpay','Bitcoin and Counterparty wallet','https://pay.holytemples.org'],['World Library','Books, audio, archives, and study','https://holytemples.org/world-library/'],['Noogle','NEO knowledge search','https://noogle.holytemples.org']],items=k==='all'?a:a.filter(i=>i[0].toLowerCase()===k.toLowerCase());this.shell(`<div class="k">Secure gateways</div><h2>${k==='all'?'Enter the NEO System':esc(items[0]?.[0]||'NEO System')}</h2><div class="grid">${items.map(i=>`<a class="card" href="${i[2]}"><div class="name">${i[0]}</div><div class="muted">${i[1]}</div><div class="tag">Open securely →</div></a>`).join('')}</div>`)}}
  const mountTempleGate=()=>{
    if(location.hostname!=='holytemples.org'||document.body?.classList.contains('logged-in')||location.pathname.startsWith('/wp-admin'))return;
    const KEY='neo_temple_gate_seen_v3',now=Date.now(),ttl=7*24*60*60*1000;
    try{const last=Number(localStorage.getItem(KEY)||0);if(last&&now-last<ttl)return}catch{}
    const host=document.createElement('div');host.id='neo-temple-gate';host.setAttribute('role','presentation');
    const root=host.attachShadow({mode:'open'});
    root.innerHTML=`<style>
      :host{all:initial}.wrap{position:fixed;inset:0;z-index:2147483000;display:grid;place-items:center;padding:20px;background:radial-gradient(circle at 50% 15%,rgba(50,255,130,.08),transparent 28%),rgba(0,4,2,.82);backdrop-filter:blur(14px);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;color:#f3fff7}.gate{position:relative;width:min(780px,100%);overflow:hidden;border:1px solid rgba(226,192,110,.35);border-radius:28px;background:radial-gradient(circle at 80% 0,rgba(99,255,155,.12),transparent 32%),linear-gradient(145deg,#020503,#09140d 52%,#030805);box-shadow:0 32px 120px rgba(0,0,0,.72),inset 0 1px 0 rgba(255,255,255,.04)}.gate:before{content:"";position:absolute;inset:-30%;background:repeating-conic-gradient(from 0deg at 50% 50%,rgba(226,192,110,.035) 0 1deg,transparent 1deg 30deg);mask-image:radial-gradient(circle,#000 0 42%,transparent 70%);pointer-events:none}.inner{position:relative;padding:clamp(28px,6vw,64px);text-align:center}.sigil{width:72px;height:72px;margin:0 auto 18px;border:1px solid rgba(226,192,110,.5);border-radius:50%;display:grid;place-items:center;color:#e2c06e;font:800 28px/1 Georgia,serif;box-shadow:0 0 40px rgba(226,192,110,.09)}.eyebrow{color:#63ff9b;font-size:.72rem;font-weight:800;letter-spacing:.22em;text-transform:uppercase}.title{margin:12px auto 10px;max-width:650px;font-family:Georgia,"Times New Roman",serif;font-size:clamp(2rem,6vw,4.6rem);font-weight:600;letter-spacing:-.045em;line-height:.96}.subtitle{margin:0 auto;max-width:590px;color:#b7c9bc;font-size:clamp(.96rem,2vw,1.12rem);line-height:1.65}.rule{width:84px;height:1px;margin:24px auto;background:linear-gradient(90deg,transparent,#e2c06e,transparent)}.actions{display:grid;grid-template-columns:1.25fr 1fr;gap:12px;max-width:560px;margin:26px auto 0}.btn{display:flex;align-items:center;justify-content:center;min-height:52px;padding:14px 18px;border-radius:14px;text-decoration:none;font-weight:800;letter-spacing:.01em;transition:.18s}.primary{background:#63ff9b;color:#031008;box-shadow:0 10px 30px rgba(99,255,155,.14)}.secondary{border:1px solid rgba(226,192,110,.35);background:rgba(255,255,255,.025);color:#f7eed8}.member{grid-column:1/-1;min-height:44px;border:0;background:transparent;color:#95aa9c;font-size:.82rem;font-weight:700}.btn:hover,.btn:focus-visible{transform:translateY(-2px);outline:none}.member:hover,.member:focus-visible{color:#63ff9b}.close{position:absolute;right:14px;top:14px;width:42px;height:42px;border:1px solid rgba(255,255,255,.1);border-radius:50%;background:rgba(255,255,255,.035);color:#d9e6dd;font-size:21px;cursor:pointer}.micro{margin-top:13px;color:#75867a;font-size:.72rem;letter-spacing:.02em}@media(max-width:620px){.wrap{padding:12px}.gate{border-radius:22px}.inner{padding:34px 20px 28px}.actions{grid-template-columns:1fr}.member{grid-column:auto}.title{font-size:clamp(2.15rem,13vw,3.5rem)}}@media(prefers-reduced-motion:no-preference){.gate{animation:neoGateIn .45s cubic-bezier(.2,.8,.2,1)}@keyframes neoGateIn{from{opacity:0;transform:translateY(12px) scale(.985)}to{opacity:1;transform:none}}}
    </style><div class="wrap"><section class="gate" role="dialog" aria-modal="true" aria-labelledby="neo-gate-title"><button class="close" aria-label="Close Temple Gate">×</button><div class="inner"><div class="sigil">∞</div><div class="eyebrow">World Temple of Karast</div><h1 class="title" id="neo-gate-title">Enter the Omniversal Church</h1><div class="rule"></div><p class="subtitle">Enter the Temple through the original Home page, join the World Congregation, or continue through NEOpass for secure member access.</p><div class="actions"><a class="btn primary" href="https://holytemples.org/home/">Enter the Temple</a><a class="btn secondary" href="https://holytemples.org/world-congregation/">Join the World Congregation</a><a class="btn member" href="https://neopass.holytemples.org">Already a member? Open NEOpass →</a></div><div class="micro">World Temple Network · Templist Portal · NEO System</div></div></section></div>`;
    const close=()=>{try{localStorage.setItem(KEY,String(Date.now()))}catch{}host.remove();document.documentElement.style.overflow=''};
    root.querySelector('.close').addEventListener('click',close);
