    }

    async loadProjectLineage() {
      const projectId=this.projectSelect.value;
      if(!projectId){this.projectChange.textContent='No transfer history yet.';this.projectLineage.innerHTML='';return;}
      try {
        const body=await this.api(`/api/ai/projects/${encodeURIComponent(projectId)}/transfers`);
        this.projectChange.textContent=body.comparison?.summary||'No transfer history yet.';
        this.projectLineage.innerHTML=(body.transfers||[]).map(t=>`<div class="lineage-item"><b>${escapeHtml(t.direction)}</b> · ${escapeHtml(t.source||'NEOsync')}<br><span class="meta">${escapeHtml(t.summary||'Transfer recorded')} · ${escapeHtml(t.createdAt||'')}</span></div>`).join('');
      } catch(error){this.projectChange.textContent=error.message;}
    }

    async recordProjectTransfer(direction) {
      const projectId=this.projectSelect.value; if(!projectId){this.projectChange.textContent='Select or create a project first.';return;}
      if(!this.threadId){this.projectChange.textContent='Open a NEOsync thread first.';return;}
