        let content='',summary='';
        if(direction==='neo-to-muse'){ const brief=await this.api(`/api/ai/threads/${encodeURIComponent(this.threadId)}/muse-brief`); content=brief.brief||''; summary='NEOsync brief exported toward Muse'; }
        else { const thread=await this.api(`/api/ai/threads/${encodeURIComponent(this.threadId)}`); content=(thread.thread?.handoffContext||thread.thread?.messages?.[0]?.text||''); summary='Muse content imported into NEOsync'; }
        const body=await this.api(`/api/ai/projects/${encodeURIComponent(projectId)}/transfers`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({direction,threadId:this.threadId,content,summary,source:direction==='neo-to-muse'?'NEOsync':'Meta Muse'})});
